        "solution": "Áp dụng công thức:\n\\(\\Delta_r H^\\circ_{298} = [\\Delta_f H^\\circ_{298}(\\ce{TiO2}) + 4 \\times \\Delta_f H^\\circ_{298}(\\ce{HCl})] - [\\Delta_f H^\\circ_{298}(\\ce{TiCl4}) + 2 \\times \\Delta_f H^\\circ_{298}(\\ce{H2O})]\\) (0,5 điểm)\n\\(\\Delta_r H^\\circ_{298} = [-945 + 4(-92)] - [-763 + 2(-286)] = -1313 - (-1335) = +22\\text{ kJ}\\). (0,5 điểm)",
