        "content": "(1,0 điểm) Thực hiện các phép tính sau (ở 25°C):\na) Tính giá trị pH của dung dịch có nồng độ ion \\(\\ce{OH<sup>-</sup>\\) là 0,001 M.\nb) Tính nồng độ mol của ion \\(\\ce{H+}\\) trong dung dịch có pH = 2,0.",
