        "level": "Vận dụng",
        "indicator": "HH3.1",
        "content": "(1,5 điểm) Từ tinh dầu hồi, người ta tách được anethole – một hợp chất thơm được dùng trong sản xuất kẹo cao su. Anethole có khối lượng mol phân tử bằng 148,0 g/mol. Phân tích nguyên tố cho thấy anethole có %C = 81,08%; %H = 8,10%; còn lại là oxygen. Hãy xác định công thức đơn giản nhất, công thức phân tử của anethole và tính tổng số nguyên tử của các nguyên tố trong một phân tử anethole.",
        "solution": "- Phần trăm khối lượng của oxygen: \\(\\%O = 100\\% - (81,08\\% + 8,10\\%) = 10,82\\%\\). (0,25 điểm)\n- Đặt công thức phân tử của anethole là \\(\\ce{C_xH_yO_z}\\). Tỉ lệ:\n\\(x : y : z = \\frac{81,08}{12} : \\frac{8,10}{1} : \\frac{10,82}{16} = 6,757 : 8,10 : 0,676 = 10 : 12 : 1\\). (0,5 điểm)\n- Công thức đơn giản nhất của anethole là \\(\\ce{C10H12O}\\). Suy ra CTPT có dạng \\(\\ce{(C10H12O)_n}\\). (0,25 điểm)\n- Vì \\(M = 148,0\\text{ g/mol} \\implies 148n = 148 \\implies n = 1\\). Vậy CTPT của anethole là \\(\\ce{C10H12O}\\), tổng số nguyên tử trong phân tử là \\(10 + 12 + 1 = 23\\). (0,5 điểm)",
        "chapter": "Chương 3: Đại cương về hóa học hữu cơ"
