        "topic": "Chương 6: Hợp chất carbonyl - Carboxylic acid",
        "level": "Vận dụng",
        "indicator": "HH1.6",
        "content": "Cho 4,5 gam formic aldehyde (\\(\\ce{HCHO}\\), M = 30) phản ứng hoàn toàn với lượng dư dung dịch \\(\\ce{AgNO3/NH3}\\) đun nóng, thu được m gam kết tủa bạc (Ag, M = 108). Giá trị của m là bao nhiêu?",
        "answer": "64,8",
        "explain": "\\(n_{\\ce{HCHO}} = \\frac{4,5}{30} = 0,15\\text{ mol}\\). Vì 1 mol \\(\\ce{HCHO}\\) tráng bạc tạo 4 mol Ag nên \\(n_{\\ce{Ag}} = 4 \\times 0,15 = 0,6\\text{ mol} \\implies m_{\\ce{Ag}} = 0,6 \\times 108 = 64,8\\text{ gam}\\).",
